namespace Overclock {
 sealed class MetricCard:Control {
  public string Title="",Primary="—",Unit="",Device="",Secondary="",Footnote="",RingText="—",ArtKey;public float Level=-1;public float[] Series=new float[0];public Color Accent=Theme.Accent;public StorageCapacity Capacity;public bool Compact;
  readonly DarkTip deviceTip=new DarkTip();protected override void Dispose(bool disposing){if(disposing)deviceTip.Dispose();base.Dispose(disposing);}
  public MetricCard(){DoubleBuffered=true;BackColor=Theme.Background;Cursor=Cursors.Hand;TabStop=true;AccessibleRole=AccessibleRole.PushButton;}
  protected override void OnKeyDown(KeyEventArgs e){base.OnKeyDown(e);if(e.KeyCode==Keys.Enter||e.KeyCode==Keys.Space){OnClick(EventArgs.Empty);e.Handled=true;}}
  public void Set(string title,string primary,string unit,string device,string secondary,string footnote,float level,string ring,float[] series){string signature=title+primary+unit+device+secondary+footnote+level+ring+ArtKey+string.Join(",",series.Select(x=>x.ToString("0.0")).ToArray())+(Capacity==null?"":Capacity.PhysicalBytes+"/"+Capacity.VolumeBytes+"/"+Capacity.FreeBytes+string.Join("",Capacity.Disks.Select(d=>d.Name).ToArray()));if(Tag as string==signature)return;Tag=signature;Title=title;Primary=primary;Unit=unit;Device=device;deviceTip.SetToolTip(this,device);Secondary=secondary;Footnote=footnote;Level=level;RingText=ring;Series=series;AccessibleName=title+" "+device+" "+primary+unit+" "+secondary;Invalidate();}
  void TextAt(Graphics g,string value,float size,RectangleF r,Color color,bool bold=false,bool italic=false){using(var font=new Font("Segoe UI",size,(bold?FontStyle.Bold:FontStyle.Regular)|(italic?FontStyle.Italic:FontStyle.Regular),GraphicsUnit.Pixel))using(var brush=new SolidBrush(color))using(var format=new StringFormat{Trimming=StringTrimming.EllipsisWord,FormatFlags=StringFormatFlags.LineLimit})g.DrawString(value??"",font,brush,r,format);}
  void Ring(Graphics g,RectangleF r){Color color=Title=="CPU"||Title=="GPU"||Title=="Temperature"?Theme.Warning:Title=="Memory"||Title=="Network"||Title=="Remaining life"?Theme.Mint:Theme.Accent;using(var p=new Pen(Theme.Line,8))g.DrawArc(p,r,0,360);if(Level>=0)using(var p=new Pen(color,8){StartCap=LineCap.Round,EndCap=LineCap.Round})g.DrawArc(p,r,-90,Math.Max(1,Math.Min(100,Level)*3.6f));else if(Title=="Network"||Title=="Sensors")using(var p=new Pen(color,3))g.DrawArc(p,r,0,360);using(var font=new Font("Segoe UI",Title=="CPU"||Title=="GPU"||Title=="Memory"?26:18,FontStyle.Bold,GraphicsUnit.Pixel))using(var b=new SolidBrush(Level>=0?color:Theme.Text))using(var f=new StringFormat{Alignment=StringAlignment.Center,LineAlignment=StringAlignment.Center})g.DrawString(RingText,font,b,r,f);}
  void History(Graphics g,float w,float top,float height,float pad){if(Series.Length<2){TextAt(g,"Waiting for live history",14,new RectangleF(pad,top,w-pad*2,height),Theme.Muted);return;}using(var p=new Pen(Theme.Line))for(int i=0;i<3;i++)g.DrawLine(p,pad,top+i*height/2,w-pad,top+i*height/2);float max=Title=="Network"?Math.Max(1,Series.Max()*1.15f):100;var points=Series.Select((v,i)=>new PointF(pad+i*(w-pad*2)/(Series.Length-1),top+height-Math.Max(0,Math.Min(max,v))*height/max)).ToArray();using(var area=new GraphicsPath()){area.AddLines(points);area.AddLine(points[points.Length-1],new PointF(w-pad,top+height));area.AddLine(new PointF(w-pad,top+height),new PointF(pad,top+height));area.CloseFigure();using(var b=new LinearGradientBrush(new PointF(0,top),new PointF(0,top+height+1),Color.FromArgb(115,Accent),Color.FromArgb(15,Accent)))g.FillPath(b,area);}using(var p=new Pen(Accent,2))g.DrawLines(p,points);}
  void Artwork(Graphics g,float w,float h){if(Title=="Network"&&ArtKey==null){PrecisionPaint.Art(g,"native-network",new RectangleF(w*.56f,5,w*.44f,135));return;}if(DashboardArt.Get(ArtKey)!=null){PrecisionPaint.Art(g,ArtKey,new RectangleF(w*.56f,-2,w*.44f,Math.Min(160,h*.42f)));return;}using(var p=new Pen(Color.FromArgb(110,Theme.Secondary),2)){float x=w-95,y=65;g.DrawRectangle(p,x,y,62,44);for(int i=0;i<4;i++){g.DrawLine(p,x-6,y+6+i*10,x,y+6+i*10);g.DrawLine(p,x+62,y+6+i*10,x+68,y+6+i*10);}}}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;float s=g.DpiX/96,w=Width/s,h=Height/s;var state=g.Save();g.ScaleTransform(s,s);g.SmoothingMode=SmoothingMode.AntiAlias;using(var shape=Theme.Angular(new RectangleF(.5f,.5f,w-1,h-1),11)){
   PrecisionPaint.Surface(g,new RectangleF(.5f,.5f,w-1,h-1));g.SetClip(shape);
   if(Compact){TextAt(g,Title.ToUpperInvariant(),18,new RectangleF(18,12,w-36,25),Theme.Text,true);TextAt(g,Primary,34,new RectangleF(18,47,w-100,48),Theme.Text,true);Ring(g,new RectangleF(w-87,43,63,63));TextAt(g,Unit,13,new RectangleF(18,99,w-32,25),Theme.Muted);if(h>195)History(g,w,h-65,43,18);}
   else if(h<285){PrecisionPaint.Ribbon(g,Title,new RectangleF(1,9,w-4,35),18);TextAt(g,Primary,32,new RectangleF(18,60,w-96,48),Theme.Text,true);Ring(g,new RectangleF(w-74,65,50,50));TextAt(g,Unit,14,new RectangleF(18,112,w-30,28),Theme.Muted);TextAt(g,Device,15,new RectangleF(18,146,w-32,28),Theme.Text,true);TextAt(g,Secondary,13,new RectangleF(18,178,w-32,48),Theme.Muted);}
   else{Artwork(g,w,h);PrecisionPaint.Ribbon(g,Title.ToUpperInvariant(),new RectangleF(1,9,w*.52f+20,40),23);
    if(Title=="Storage"&&Capacity!=null)DrawStorage(g,w,h);
    else{bool hardware=Title=="CPU"||Title=="GPU";if(hardware)TextAt(g,Device.Replace("-Core","‑Core"),Device.Length>32?19:20,new RectangleF(20,65,w*.54f-12,77),Theme.Text,true);float y=hardware?145:Title=="Memory"?102:89;float font=Primary.Length>5?44:62;TextAt(g,Primary,font,new RectangleF(20,y,w-120,80),Theme.Text,true);TextAt(g,Unit,17,new RectangleF(20,y+77,w-130,28),Theme.Muted);Ring(g,new RectangleF(w-124,hardware?146:Title=="Memory"?145:136,98,98));if(!hardware)TextAt(g,Device,18,new RectangleF(20,Title=="Memory"?226:198,w-40,30),Theme.Text,true);TextAt(g,Secondary,15,new RectangleF(20,hardware?244:Title=="Memory"?257:233,w-40,26),Theme.Muted);if(Title=="CPU"||Title=="GPU"||Title=="Network")History(g,w,h-92,55,20);using(var p=new Pen(Theme.Line))g.DrawLine(p,20,h-44,w-20,h-44);TextAt(g,Footnote.Replace("→",""),14,new RectangleF(20,h-34,w-54,27),Theme.Text);TextAt(g,"→",22,new RectangleF(w-43,h-39,30,30),Theme.Accent,true);}
   }g.ResetClip();using(var p=new Pen(Theme.Line))g.DrawPath(p,shape);if(Focused)using(var p=new Pen(Theme.Accent))g.DrawPath(p,shape);
  }g.Restore(state);}
  void DrawStorage(Graphics g,float w,float h){TextAt(g,StorageFormat.Size(Capacity.PhysicalBytes),44,new RectangleF(20,85,w-38,63),Theme.Text,true);TextAt(g,"installed internal storage",17,new RectangleF(20,150,w-40,28),Theme.Muted);float y=190,width=w-40;using(var b=new SolidBrush(Theme.Line))g.FillRectangle(b,20,y,width,17);if(Capacity.PhysicalBytes>0&&Capacity.VolumeCount>0){float used=(float)Math.Min(1,Capacity.UsedBytes/(double)Capacity.PhysicalBytes),free=(float)Math.Min(1-used,Capacity.FreeBytes/(double)Capacity.PhysicalBytes);using(var b=new LinearGradientBrush(new PointF(20,y),new PointF(20,y+18),Theme.Accent,Theme.PrimaryHover))g.FillRectangle(b,20,y,width*used,17);using(var b=new SolidBrush(Theme.Secondary))g.FillRectangle(b,20+width*used,y,width*free,17);TextAt(g,"Used "+StorageFormat.Size(Capacity.UsedBytes),15,new RectangleF(20,y+24,width/2,25),Theme.Accent);TextAt(g,"Free "+StorageFormat.Size(Capacity.FreeBytes),15,new RectangleF(20+width/2,y+24,width/2,25),Theme.Text);}else TextAt(g,"Volume free space unavailable",15,new RectangleF(20,y+24,width,24),Theme.Muted);
   var drives=Capacity.Disks.OrderBy(d=>d.MediaType=="SSD"?0:1).ThenBy(d=>d.Number).ToArray();int count=Math.Min(drives.Length,Math.Max(0,(int)(h-289)/25));for(int i=0;i<count;i++)TextAt(g,"#"+drives[i].Number+"  "+drives[i].Name,15,new RectangleF(20,247+i*25,width,25),Theme.Text);using(var p=new Pen(Theme.Line))g.DrawLine(p,20,h-44,w-20,h-44);string note=count<drives.Length?"+ "+(drives.Length-count)+" more drives · Details →":Capacity.OtherBytes>1073741824?StorageFormat.Size(Capacity.OtherBytes)+" other / unmounted · Details →":"Physical drives · Details →";TextAt(g,note,13,new RectangleF(20,h-33,width,27),Theme.Text);
  }
 }
 static class SoftNeon {
  public static Bitmap Create(GraphicsPath glyphs,Rectangle bounds,int padding,float scale){int width=bounds.Width+padding*2,height=bounds.Height+padding*2;float[] alpha=new float[width*height];using(var mask=new Bitmap(width,height,PixelFormat.Format32bppArgb)){using(var graphics=Graphics.FromImage(mask))using(var local=(GraphicsPath)glyphs.Clone())using(var transform=new Matrix()){graphics.Clear(Color.Transparent);graphics.SmoothingMode=SmoothingMode.AntiAlias;transform.Translate(padding-bounds.X,padding-bounds.Y);local.Transform(transform);graphics.FillPath(Brushes.White,local);}var pixels=mask.LockBits(new Rectangle(0,0,width,height),ImageLockMode.ReadOnly,PixelFormat.Format32bppArgb);try{byte[] bytes=new byte[pixels.Stride*height];Marshal.Copy(pixels.Scan0,bytes,0,bytes.Length);for(int y=0;y<height;y++)for(int x=0;x<width;x++)alpha[y*width+x]=bytes[y*pixels.Stride+x*4+3];}finally{mask.UnlockBits(pixels);}}
   var wide=Blur(alpha,width,height,4.2f*scale);var core=Blur(alpha,width,height,1.6f*scale);var bitmap=new Bitmap(width,height,PixelFormat.Format32bppArgb);var data=bitmap.LockBits(new Rectangle(0,0,width,height),ImageLockMode.WriteOnly,PixelFormat.Format32bppArgb);try{byte[] bytes=new byte[data.Stride*height];for(int y=0;y<height;y++)for(int x=0;x<width;x++){int pixel=y*width+x,offset=y*data.Stride+x*4;bytes[offset]=84;bytes[offset+1]=58;bytes[offset+2]=255;bytes[offset+3]=(byte)Math.Min(115,wide[pixel]*.58f+core[pixel]*.20f);}Marshal.Copy(bytes,0,data.Scan0,bytes.Length);}finally{bitmap.UnlockBits(data);}return bitmap;
  }
  static float[] Blur(float[] source,int width,int height,float sigma){int radius=(int)Math.Ceiling(sigma*3);float[] kernel=new float[radius*2+1];double total=0;for(int i=-radius;i<=radius;i++){kernel[i+radius]=(float)Math.Exp(-(i*i)/(2*sigma*sigma));total+=kernel[i+radius];}for(int i=0;i<kernel.Length;i++)kernel[i]/=(float)total;var horizontal=new float[source.Length];var result=new float[source.Length];for(int y=0;y<height;y++)for(int x=0;x<width;x++){float value=0;for(int i=-radius;i<=radius;i++)if(x+i>=0&&x+i<width)value+=source[y*width+x+i]*kernel[i+radius];horizontal[y*width+x]=value;}for(int y=0;y<height;y++)for(int x=0;x<width;x++){float value=0;for(int i=-radius;i<=radius;i++)if(y+i>=0&&y+i<height)value+=horizontal[(y+i)*width+x]*kernel[i+radius];result[y*width+x]=value;}return result;}
 }
